import os

import psycopg2
import redis
from flask import Flask, jsonify

app = Flask(__name__)

DATABASE_URL = os.environ.get("DATABASE_URL", "")
REDIS_URL = os.environ.get("REDIS_URL", "")


def _db_ok():
    conn = psycopg2.connect(DATABASE_URL, connect_timeout=3)
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1")
    finally:
        conn.close()
    return True


def _cache_ok():
    return redis.Redis.from_url(REDIS_URL, socket_timeout=3).ping()


@app.get("/healthz")
def healthz():
    checks = {}
    for name, check in (("db", _db_ok), ("cache", _cache_ok)):
        try:
            check()
            checks[name] = "ok"
        except Exception as exc:
            checks[name] = "error: {}".format(exc.__class__.__name__)

    if all(value == "ok" for value in checks.values()):
        return jsonify(status="ok", checks=checks), 200
    return jsonify(status="error", checks=checks), 503


@app.get("/")
def index():
    return jsonify(service="api", status="ok")

user nginx;
worker_processes auto;

events {
  worker_connections 1024;
}

http {
  include       /etc/nginx/mime.types;
  default_type  application/json;

  sendfile             on;
  tcp_nopush           on;
  server_tokens        off;
  keepalive_timeout    65;
  client_max_body_size 10m;

  gzip         on;
  gzip_proxied any;
  gzip_types   application/json;

  upstream api_upstream {
    server api:8000;
    keepalive 16;
  }

  server {
    listen 80;
    server_name _;

    location = /healthz {
      access_log off;
      proxy_pass http://api_upstream;
      proxy_http_version 1.1;
      proxy_set_header Connection "";
      proxy_set_header Host              $host;
      proxy_set_header X-Real-IP         $remote_addr;
      proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
      proxy_set_header X-Forwarded-Proto $scheme;
      proxy_connect_timeout 3s;
      proxy_send_timeout   10s;
      proxy_read_timeout   10s;
    }

    location / {
      proxy_pass http://api_upstream;
      proxy_http_version 1.1;
      proxy_set_header Connection "";
      proxy_set_header Host              $host;
      proxy_set_header X-Real-IP         $remote_addr;
      proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
      proxy_set_header X-Forwarded-Proto $scheme;
      proxy_connect_timeout 5s;
      proxy_send_timeout   60s;
      proxy_read_timeout   60s;
      proxy_buffering      on;
      proxy_buffers        8 16k;
    }
  }
}
